<div id="app-content"><div class="erp-page"><div class="erp-head"><div><h1>Angebote</h1><p class="erp-sub">Angebot erfassen, freigeben und in einen Auftrag übernehmen.</p></div></div><form class="erp-form-card" method="post" action="<?php p($url->linkToRoute('reinhardterp.business.saveOffer'));?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><div class="erp-form-grid"><div><label>Kunde</label><select name="customerId" required><?php foreach($_['customers'] as $c):?><option value="<?php p($c['id']);?>"><?php p($c['name']);?></option><?php endforeach;?></select></div><div><label>Projekt</label><select name="projectId"><option value="">ohne Projekt</option><?php foreach($_['projects'] as $p):?><option value="<?php p($p['id']);?>"><?php p($p['project_no'].' · '.$p['title']);?></option><?php endforeach;?></select></div><div class="erp-span-2"><label>Titel</label><input name="title" required></div><div class="erp-span-2"><label>Leistungsbeschreibung</label><textarea name="description" rows="4" required></textarea></div><div><label>Menge</label><input type="number" step="0.01" name="quantity" value="1"></div><div><label>Einheit</label><input name="unit" value="Stk."></div><div><label>Einzelpreis netto</label><input type="number" step="0.01" name="unitPrice" value="0"></div><div><label>USt.</label><input type="number" step="0.01" name="vatRate" value="19"></div><div><label>Gültig bis</label><input type="date" name="validUntil"></div><div class="erp-span-2"><label>Notizen</label><textarea name="notes" rows="2"></textarea></div></div><button class="button primary">Angebot anlegen</button></form><div class="erp-table"><table><thead><tr><th>Nummer</th><th>Datum</th><th>Kunde</th><th>Titel</th><th>Status</th><th>Netto</th><th>Brutto</th></tr></thead><tbody><?php foreach($_['offers'] as $o):?><tr><td><a href="<?php p($url->linkToRoute('reinhardterp.business.offerDetail',['id'=>$o['id']]));?>"><strong><?php p($o['offer_no']);?></strong></a></td><